#define PI 3.14159265358979323846

vec2 brickTile(vec2 _st, float _zoom){
    _st *= _zoom;

    float isEvenR = step(1.0,mod(_st.y,2.0));
    float isEvenC = step(1.0,mod(_st.x,2.0));
    float sine = step(0.0,sin(PI*iTime));

    _st.x += (isEvenR*2.0-1.0)*iTime*sine;
    _st.y += (isEvenC*2.0-1.0)*iTime*(1.0-sine);
    return fract(_st);
}

float circle(in vec2 _st, in float _radius){
    vec2 l = _st-vec2(0.5);
    return 1.-smoothstep(_radius-(_radius*0.01),
                         _radius+(_radius*0.01),
                         dot(l,l)*4.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 st = fragCoord.xy/iResolution.xy;
    st.x *= iResolution.x/iResolution.y;
    vec3 color = vec3(0.0);

    st = brickTile(st,10.0);

    vec2 offset = vec2(0.01,0.01);
    color.r = 1.0-circle(st+offset, 0.2);
    color.g = 1.0-circle(st-offset, 0.2);
    color.b = 1.0-circle(st, 0.2);

    fragColor = vec4(color,1.0);
}
